INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_acc_bank_001', 'subj_wassce_accounting', 'topic_acc_bank', 'Which of the following would cause the bank balance to be higher than the cash book balance?', '["Unpresented cheques","Bank charges","Direct credits not yet recorded","Dishonored cheques"]', 2, 'Direct credits (like standing orders received) that appear in the bank statement but not yet in the cash book would make the bank balance higher.', 'medium', 'multiple_choice', datetime('now')),
('q_acc_bank_002', 'subj_wassce_accounting', 'topic_acc_bank', 'Unpresented cheques are cheques that have been:', '["Received but not deposited","Issued but not yet paid by the bank","Cancelled by the drawer","Returned by the bank"]', 1, 'Unpresented cheques are cheques issued by the business but not yet presented to or cleared by the bank.', 'easy', 'multiple_choice', datetime('now')),
('q_acc_bank_003', 'subj_wassce_accounting', 'topic_acc_bank', 'The purpose of a bank reconciliation statement is to:', '["Calculate profit","Explain differences between cash book and bank statement","Prepare final accounts","Record daily transactions"]', 1, 'Bank reconciliation explains and accounts for differences between the cash book balance and bank statement balance.', 'easy', 'multiple_choice', datetime('now')),
('q_acc_bank_004', 'subj_wassce_accounting', 'topic_acc_bank', 'Uncredited deposits are:', '["Cheques issued but not cleared","Deposits made but not yet reflected in bank statement","Bank charges","Standing orders"]', 1, 'Uncredited deposits (also called deposits in transit) are deposits made but not yet appearing in the bank statement.', 'medium', 'multiple_choice', datetime('now')),
('q_acc_bank_005', 'subj_wassce_accounting', 'topic_acc_bank', 'When preparing a bank reconciliation, bank charges should be:', '["Added to cash book balance","Deducted from cash book balance","Added to bank statement balance","Ignored"]', 1, 'Bank charges reduce the cash book balance when updating it to agree with the bank statement.', 'medium', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_acc_err_001', 'subj_wassce_accounting', 'topic_acc_errors', 'An error of principle occurs when:', '["A transaction is recorded in wrong class of account","Figures are transposed","An entry is completely omitted","Both debit and credit are wrong"]', 0, 'An error of principle involves recording a transaction in the wrong class of account (e.g., capital expenditure as revenue expenditure).', 'medium', 'multiple_choice', datetime('now')),
('q_acc_err_002', 'subj_wassce_accounting', 'topic_acc_errors', 'A suspense account is used to:', '["Record suspicions","Temporarily hold differences until errors are found","Record bad debts","Balance the bank account"]', 1, 'A suspense account temporarily holds the difference in a trial balance until the error causing it is found and corrected.', 'easy', 'multiple_choice', datetime('now')),
('q_acc_err_003', 'subj_wassce_accounting', 'topic_acc_errors', 'Which error will NOT affect the trial balance?', '["Casting error","Error of original entry","Single entry error","Extraction error"]', 1, 'An error of original entry (wrong amount on both sides) will not affect the trial balance as debits still equal credits.', 'hard', 'multiple_choice', datetime('now')),
('q_acc_err_004', 'subj_wassce_accounting', 'topic_acc_errors', 'An error of commission involves:', '["Recording in wrong personal account within same class","Recording in wrong class of account","Omitting an entry","Making a calculation mistake"]', 0, 'An error of commission is posting to the wrong account within the same class (e.g., wrong debtor account).', 'medium', 'multiple_choice', datetime('now')),
('q_acc_err_005', 'subj_wassce_accounting', 'topic_acc_errors', 'Compensating errors are errors that:', '["Cancel each other out","Are made on purpose","Always affect profit","Cannot be corrected"]', 0, 'Compensating errors are two or more errors that cancel each other out, so the trial balance still agrees.', 'medium', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_acc_final_001', 'subj_wassce_accounting', 'topic_acc_final', 'Gross profit is calculated as:', '["Sales minus Cost of Goods Sold","Sales minus all expenses","Net profit plus expenses","Total revenue minus total costs"]', 0, 'Gross Profit = Sales Revenue - Cost of Goods Sold. It shows profit before operating expenses.', 'easy', 'multiple_choice', datetime('now')),
('q_acc_final_002', 'subj_wassce_accounting', 'topic_acc_final', 'Which of the following appears in the Balance Sheet?', '["Sales","Purchases","Rent expense","Debtors"]', 3, 'Debtors (trade receivables) is an asset that appears in the Balance Sheet. Sales, purchases, and rent are in the Income Statement.', 'easy', 'multiple_choice', datetime('now')),
('q_acc_final_003', 'subj_wassce_accounting', 'topic_acc_final', 'Carriage inwards is added to:', '["Sales","Purchases","Gross profit","Net profit"]', 1, 'Carriage inwards (cost of transporting goods bought) is added to purchases as part of Cost of Goods Sold.', 'medium', 'multiple_choice', datetime('now')),
('q_acc_final_004', 'subj_wassce_accounting', 'topic_acc_final', 'The accounting equation states that:', '["Assets = Liabilities","Assets = Capital + Liabilities","Capital = Assets + Liabilities","Assets = Capital - Liabilities"]', 1, 'The fundamental accounting equation is Assets = Capital + Liabilities (or Assets = Equity + Liabilities).', 'easy', 'multiple_choice', datetime('now')),
('q_acc_final_005', 'subj_wassce_accounting', 'topic_acc_final', 'Closing stock appears in:', '["Trading account only","Balance sheet only","Both trading account and balance sheet","Profit and loss account only"]', 2, 'Closing stock appears as a deduction in the Trading Account and as a current asset in the Balance Sheet.', 'medium', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_acc_part_001', 'subj_wassce_accounting', 'topic_acc_partnership', 'In the absence of a partnership agreement, profits are shared:', '["According to capital ratio","According to drawings","Equally among partners","According to age"]', 2, 'Without a partnership agreement, the Partnership Act 1890 states profits must be shared equally.', 'medium', 'multiple_choice', datetime('now')),
('q_acc_part_002', 'subj_wassce_accounting', 'topic_acc_partnership', 'Interest on capital is:', '["An expense of the business","An appropriation of profit","A liability","A revenue item"]', 1, 'Interest on capital is an appropriation (distribution) of profit to partners, not a business expense.', 'medium', 'multiple_choice', datetime('now')),
('q_acc_part_003', 'subj_wassce_accounting', 'topic_acc_partnership', 'The current account of a partner shows:', '["Fixed capital only","Running balance of transactions with partner","Only drawings","Only salary"]', 1, 'The current account shows the running balance of a partner including share of profit, salary, interest, and drawings.', 'medium', 'multiple_choice', datetime('now')),
('q_acc_part_004', 'subj_wassce_accounting', 'topic_acc_partnership', 'When a new partner is admitted, goodwill is:', '["Ignored","Written off immediately","Only recorded if paid in cash","Credited to old partners in old ratio"]', 3, 'Goodwill on admission is credited to old partners'' capital accounts in their old profit-sharing ratio.', 'hard', 'multiple_choice', datetime('now')),
('q_acc_part_005', 'subj_wassce_accounting', 'topic_acc_partnership', 'Partner''s salary is shown in the:', '["Trading account","Profit and loss account","Appropriation account","Balance sheet only"]', 2, 'Partner salaries are appropriations of profit shown in the Appropriation Account, not expenses.', 'medium', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_acc_npo_001', 'subj_wassce_accounting', 'topic_acc_nonprofit', 'The equivalent of profit in a non-profit organization is called:', '["Net income","Surplus","Revenue","Gain"]', 1, 'Non-profit organizations refer to excess of income over expenditure as surplus (not profit).', 'easy', 'multiple_choice', datetime('now')),
('q_acc_npo_002', 'subj_wassce_accounting', 'topic_acc_nonprofit', 'A Receipts and Payments Account is:', '["Same as income and expenditure account","A summary of cash transactions","A balance sheet","A trading account"]', 1, 'Receipts and Payments Account summarizes all cash received and paid during a period.', 'easy', 'multiple_choice', datetime('now')),
('q_acc_npo_003', 'subj_wassce_accounting', 'topic_acc_nonprofit', 'Subscriptions received in advance are:', '["Income for the current year","Liabilities","Assets","Accumulated fund"]', 1, 'Subscriptions received in advance are liabilities as the service is yet to be provided.', 'medium', 'multiple_choice', datetime('now')),
('q_acc_npo_004', 'subj_wassce_accounting', 'topic_acc_nonprofit', 'The Accumulated Fund in a club represents:', '["Cash in hand","Capital or net worth","Total subscriptions","Annual surplus"]', 1, 'Accumulated Fund represents the capital or net worth of a non-profit organization (assets minus liabilities).', 'medium', 'multiple_choice', datetime('now')),
('q_acc_npo_005', 'subj_wassce_accounting', 'topic_acc_nonprofit', 'Life membership fees should be:', '["Treated as income immediately","Spread over expected membership years","Treated as liability","Ignored"]', 1, 'Life membership fees should be spread over the expected membership period using the matching principle.', 'hard', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_eco_cost_001', 'subj_wassce_economics', 'topic_eco_costs', 'Fixed costs are costs that:', '["Change with output","Remain constant regardless of output","Are always zero","Equal variable costs"]', 1, 'Fixed costs (like rent, insurance) remain constant regardless of the level of output in the short run.', 'easy', 'multiple_choice', datetime('now')),
('q_eco_cost_002', 'subj_wassce_economics', 'topic_eco_costs', 'Marginal cost is the cost of producing:', '["The first unit","The last unit","One more unit","All units"]', 2, 'Marginal cost is the additional cost of producing one more unit of output.', 'medium', 'multiple_choice', datetime('now')),
('q_eco_cost_003', 'subj_wassce_economics', 'topic_eco_costs', 'Average cost is calculated as:', '["Total cost × quantity","Total cost ÷ quantity","Marginal cost × quantity","Fixed cost + variable cost"]', 1, 'Average cost (AC) = Total Cost / Quantity produced.', 'easy', 'multiple_choice', datetime('now')),
('q_eco_cost_004', 'subj_wassce_economics', 'topic_eco_costs', 'Total revenue is calculated as:', '["Price × quantity sold","Price + quantity sold","Price ÷ quantity sold","Price - cost"]', 0, 'Total Revenue (TR) = Price × Quantity sold.', 'easy', 'multiple_choice', datetime('now')),
('q_eco_cost_005', 'subj_wassce_economics', 'topic_eco_costs', 'A firm makes normal profit when:', '["TR > TC","TR < TC","TR = TC","MR = MC"]', 2, 'Normal profit occurs when Total Revenue equals Total Cost (TR = TC), meaning the firm covers all costs including opportunity cost.', 'medium', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_eco_prod_001', 'subj_wassce_economics', 'topic_eco_production', 'The law of diminishing returns states that:', '["Returns always decrease","Eventually, adding more of a variable factor yields less additional output","Fixed costs always increase","Production always increases"]', 1, 'The law of diminishing returns states that adding more of a variable factor to fixed factors eventually yields diminishing marginal returns.', 'medium', 'multiple_choice', datetime('now')),
('q_eco_prod_002', 'subj_wassce_economics', 'topic_eco_production', 'The four factors of production are:', '["Land, labor, money, enterprise","Land, labor, capital, enterprise","Land, labor, capital, government","Land, labor, capital, technology"]', 1, 'The four factors of production are Land, Labor, Capital, and Enterprise (entrepreneurship).', 'easy', 'multiple_choice', datetime('now')),
('q_eco_prod_003', 'subj_wassce_economics', 'topic_eco_production', 'The reward for enterprise is:', '["Wages","Rent","Interest","Profit"]', 3, 'Entrepreneurs receive profit as their reward. Wages go to labor, rent to land, and interest to capital.', 'easy', 'multiple_choice', datetime('now')),
('q_eco_prod_004', 'subj_wassce_economics', 'topic_eco_production', 'Marginal product is:', '["Total output divided by inputs","Additional output from one more unit of input","Average output per worker","Maximum possible output"]', 1, 'Marginal product is the additional output gained from employing one more unit of a variable factor.', 'medium', 'multiple_choice', datetime('now')),
('q_eco_prod_005', 'subj_wassce_economics', 'topic_eco_production', 'Division of labor leads to:', '["Decreased productivity","Increased specialization","Higher unemployment","Lower quality"]', 1, 'Division of labor increases specialization, which improves efficiency and productivity.', 'easy', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_eco_nat_001', 'subj_wassce_economics', 'topic_eco_national', 'GDP stands for:', '["General Domestic Product","Gross Domestic Product","Gross Development Plan","General Development Product"]', 1, 'GDP stands for Gross Domestic Product - the total value of goods and services produced within a country.', 'easy', 'multiple_choice', datetime('now')),
('q_eco_nat_002', 'subj_wassce_economics', 'topic_eco_national', 'The difference between GDP and GNP is:', '["There is no difference","GNP includes net income from abroad","GDP includes net income from abroad","GNP only counts manufacturing"]', 1, 'GNP = GDP + Net income from abroad. GNP includes earnings of citizens abroad minus foreigners'' earnings domestically.', 'medium', 'multiple_choice', datetime('now')),
('q_eco_nat_003', 'subj_wassce_economics', 'topic_eco_national', 'The income method of measuring national income adds up:', '["All expenditures","All incomes earned","All outputs produced","All imports and exports"]', 1, 'The income method sums all incomes earned in production - wages, rent, interest, and profits.', 'medium', 'multiple_choice', datetime('now')),
('q_eco_nat_004', 'subj_wassce_economics', 'topic_eco_national', 'Per capita income is:', '["Total income","National income divided by population","Income of capital owners","Government revenue"]', 1, 'Per capita income = National Income / Population. It shows average income per person.', 'easy', 'multiple_choice', datetime('now')),
('q_eco_nat_005', 'subj_wassce_economics', 'topic_eco_national', 'Double counting in national income is avoided by:', '["Using market prices","Using only final goods or value added method","Counting all goods","Including intermediate goods"]', 1, 'To avoid double counting, only final goods are counted, or the value added at each stage of production.', 'medium', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_eco_trade_001', 'subj_wassce_economics', 'topic_eco_trade', 'A tariff is:', '["A tax on imports","A limit on imports","A subsidy on exports","A trade agreement"]', 0, 'A tariff is a tax imposed on imported goods, making them more expensive than domestic goods.', 'easy', 'multiple_choice', datetime('now')),
('q_eco_trade_002', 'subj_wassce_economics', 'topic_eco_trade', 'The balance of trade measures:', '["Total imports and exports","Difference between visible exports and imports","Total foreign investment","Government borrowing"]', 1, 'Balance of Trade = Value of Visible Exports - Value of Visible Imports (goods only).', 'medium', 'multiple_choice', datetime('now')),
('q_eco_trade_003', 'subj_wassce_economics', 'topic_eco_trade', 'A quota is:', '["A tax on imports","A physical limit on imports","A type of currency","An export subsidy"]', 1, 'A quota is a quantitative restriction limiting the amount of a good that can be imported.', 'easy', 'multiple_choice', datetime('now')),
('q_eco_trade_004', 'subj_wassce_economics', 'topic_eco_trade', 'Comparative advantage means:', '["Producing everything cheaper","Producing a good at lower opportunity cost","Having more resources","Trading with neighbors"]', 1, 'Comparative advantage is the ability to produce a good at a lower opportunity cost than another country.', 'medium', 'multiple_choice', datetime('now')),
('q_eco_trade_005', 'subj_wassce_economics', 'topic_eco_trade', 'Devaluation of currency makes:', '["Exports cheaper and imports expensive","Exports expensive and imports cheaper","No difference to trade","Both exports and imports cheaper"]', 0, 'Devaluation makes exports cheaper (more competitive) and imports more expensive.', 'medium', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_gov_party_001', 'subj_wassce_government', 'topic_gov_parties', 'A one-party system is characterized by:', '["Many parties competing","Only one legal political party","Two dominant parties","Coalition governments"]', 1, 'In a one-party system, only one political party is legally allowed to hold power.', 'easy', 'multiple_choice', datetime('now')),
('q_gov_party_002', 'subj_wassce_government', 'topic_gov_parties', 'The main function of political parties is to:', '["Make laws directly","Contest elections and form government","Enforce laws","Interpret laws"]', 1, 'Political parties contest elections to gain power and form government to implement their policies.', 'easy', 'multiple_choice', datetime('now')),
('q_gov_party_003', 'subj_wassce_government', 'topic_gov_parties', 'A coalition government is formed when:', '["One party wins majority","No single party wins majority","The military takes over","The president resigns"]', 1, 'A coalition is formed when no single party wins enough seats for a majority, so parties combine.', 'medium', 'multiple_choice', datetime('now')),
('q_gov_party_004', 'subj_wassce_government', 'topic_gov_parties', 'The opposition party''s role is to:', '["Support all government policies","Criticize and provide alternative policies","Form the government","Appoint ministers"]', 1, 'The opposition scrutinizes government, criticizes policies, and offers alternatives.', 'easy', 'multiple_choice', datetime('now')),
('q_gov_party_005', 'subj_wassce_government', 'topic_gov_parties', 'In a two-party system:', '["Only two parties exist","Two parties dominate and alternate in power","Coalitions are common","One party always wins"]', 1, 'In a two-party system, two major parties dominate and typically alternate in government.', 'medium', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_gov_elect_001', 'subj_wassce_government', 'topic_gov_elections', 'Universal adult suffrage means:', '["Only educated people can vote","All adults can vote regardless of status","Only men can vote","Only property owners can vote"]', 1, 'Universal adult suffrage gives all adults the right to vote regardless of gender, race, wealth, or education.', 'easy', 'multiple_choice', datetime('now')),
('q_gov_elect_002', 'subj_wassce_government', 'topic_gov_elections', 'First-past-the-post electoral system means:', '["Candidate with most votes wins","Voters rank candidates","Seats allocated by proportion of votes","Two rounds of voting"]', 0, 'In first-past-the-post, the candidate with the most votes in a constituency wins, even without a majority.', 'medium', 'multiple_choice', datetime('now')),
('q_gov_elect_003', 'subj_wassce_government', 'topic_gov_elections', 'Proportional representation ensures:', '["Winner takes all","Seats match vote proportions","Only major parties win","Gerrymandering"]', 1, 'Proportional representation allocates seats in proportion to the votes each party receives.', 'medium', 'multiple_choice', datetime('now')),
('q_gov_elect_004', 'subj_wassce_government', 'topic_gov_elections', 'A by-election is held when:', '["General elections are due","A seat becomes vacant mid-term","The president travels","Parliament is dissolved"]', 1, 'A by-election fills a vacant seat between general elections, usually due to death or resignation.', 'easy', 'multiple_choice', datetime('now')),
('q_gov_elect_005', 'subj_wassce_government', 'topic_gov_elections', 'Secret ballot ensures:', '["Faster counting","Voter privacy and freedom from intimidation","Higher turnout","Only literate people vote"]', 1, 'Secret ballot protects voter privacy, preventing intimidation and vote buying.', 'easy', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_gov_rights_001', 'subj_wassce_government', 'topic_gov_rights', 'Citizenship by birth is also called:', '["Jus sanguinis","Jus soli","Naturalization","Registration"]', 1, 'Jus soli (right of soil) grants citizenship based on place of birth.', 'medium', 'multiple_choice', datetime('now')),
('q_gov_rights_002', 'subj_wassce_government', 'topic_gov_rights', 'Fundamental human rights include:', '["Right to vote only","Right to life, liberty, and property","Right to government job","Right to free housing"]', 1, 'Fundamental rights typically include right to life, liberty, property, and dignity.', 'easy', 'multiple_choice', datetime('now')),
('q_gov_rights_003', 'subj_wassce_government', 'topic_gov_rights', 'Naturalization is:', '["Being born a citizen","Acquiring citizenship of another country","Losing citizenship","Dual citizenship"]', 1, 'Naturalization is the legal process of acquiring citizenship of a country other than one''s birth country.', 'easy', 'multiple_choice', datetime('now')),
('q_gov_rights_004', 'subj_wassce_government', 'topic_gov_rights', 'Civic responsibilities include:', '["Only paying taxes","Voting, obeying laws, and paying taxes","Only voting","Only national service"]', 1, 'Civic responsibilities include voting, paying taxes, obeying laws, and serving the nation when required.', 'easy', 'multiple_choice', datetime('now')),
('q_gov_rights_005', 'subj_wassce_government', 'topic_gov_rights', 'Rule of law means:', '["The president makes all laws","Everyone is equal before the law","Laws can be ignored","Only judges are above law"]', 1, 'Rule of law means everyone, including government officials, is subject to and equal before the law.', 'medium', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_geo_veg_001', 'subj_wassce_geography', 'topic_geo_vegetation', 'Tropical rainforests are characterized by:', '["Low rainfall","Deciduous trees","High rainfall and evergreen trees","Sparse vegetation"]', 2, 'Tropical rainforests have high rainfall (over 2000mm/year) and dense evergreen vegetation.', 'easy', 'multiple_choice', datetime('now')),
('q_geo_veg_002', 'subj_wassce_geography', 'topic_geo_vegetation', 'Savanna vegetation is found in areas with:', '["Very high rainfall throughout the year","Distinct wet and dry seasons","No rainfall","Permanent snow"]', 1, 'Savanna develops in tropical regions with distinct wet and dry seasons.', 'medium', 'multiple_choice', datetime('now')),
('q_geo_veg_003', 'subj_wassce_geography', 'topic_geo_vegetation', 'Laterite soils are:', '["Rich in humus","Reddish, leached tropical soils","Black and fertile","Found in deserts only"]', 1, 'Laterite soils are reddish tropical soils heavily leached of nutrients by high rainfall.', 'medium', 'multiple_choice', datetime('now')),
('q_geo_veg_004', 'subj_wassce_geography', 'topic_geo_vegetation', 'Desertification is caused by:', '["Too much rainfall","Overgrazing, deforestation, and climate change","Volcanic activity","Earthquakes"]', 1, 'Desertification is land degradation caused by overgrazing, deforestation, poor farming, and climate change.', 'medium', 'multiple_choice', datetime('now')),
('q_geo_veg_005', 'subj_wassce_geography', 'topic_geo_vegetation', 'The Sahel region in Africa has:', '["Rainforest vegetation","Semi-arid transitional vegetation","Desert only","Mangrove swamps"]', 1, 'The Sahel is a semi-arid transition zone between the Sahara Desert and tropical savanna.', 'medium', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_geo_set_001', 'subj_wassce_geography', 'topic_geo_settlement', 'Urbanization refers to:', '["Rural development","Growth of urban areas and urban population","Decline of cities","Agricultural expansion"]', 1, 'Urbanization is the increase in the proportion of population living in urban areas.', 'easy', 'multiple_choice', datetime('now')),
('q_geo_set_002', 'subj_wassce_geography', 'topic_geo_settlement', 'A nucleated settlement pattern is:', '["Scattered houses","Houses clustered together","Linear along a road","Houses on water"]', 1, 'Nucleated settlements have houses clustered together around a central point.', 'easy', 'multiple_choice', datetime('now')),
('q_geo_set_003', 'subj_wassce_geography', 'topic_geo_settlement', 'Push factors for rural-urban migration include:', '["Better urban jobs","Lack of rural amenities and opportunities","Urban entertainment","Better urban housing"]', 1, 'Push factors are negative aspects of rural areas that push people to migrate (lack of jobs, schools, healthcare).', 'medium', 'multiple_choice', datetime('now')),
('q_geo_set_004', 'subj_wassce_geography', 'topic_geo_settlement', 'Slums in cities result from:', '["Good urban planning","Rapid urbanization outpacing housing supply","Government policy","Declining population"]', 1, 'Slums develop when rapid urbanization exceeds the capacity to provide adequate housing.', 'medium', 'multiple_choice', datetime('now')),
('q_geo_set_005', 'subj_wassce_geography', 'topic_geo_settlement', 'A linear settlement develops:', '["In a circular pattern","Along a road, river, or railway","Around a market","Randomly"]', 1, 'Linear settlements develop along transport routes like roads, rivers, or railways.', 'easy', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_geo_res_001', 'subj_wassce_geography', 'topic_geo_resources', 'Renewable resources are those that:', '["Cannot be replaced","Can be replenished naturally","Are found underground","Are very expensive"]', 1, 'Renewable resources can be naturally replenished (forests, water, solar energy).', 'easy', 'multiple_choice', datetime('now')),
('q_geo_res_002', 'subj_wassce_geography', 'topic_geo_resources', 'Which is a non-renewable resource?', '["Timber","Solar energy","Crude oil","Fish"]', 2, 'Crude oil is non-renewable as it takes millions of years to form and cannot be replenished quickly.', 'easy', 'multiple_choice', datetime('now')),
('q_geo_res_003', 'subj_wassce_geography', 'topic_geo_resources', 'Conservation of resources means:', '["Using all resources quickly","Wise use to ensure sustainability","Avoiding all resource use","Exporting all resources"]', 1, 'Conservation is the sustainable and wise use of resources to ensure availability for future generations.', 'easy', 'multiple_choice', datetime('now')),
('q_geo_res_004', 'subj_wassce_geography', 'topic_geo_resources', 'Ghana''s main mineral exports include:', '["Diamonds only","Gold, bauxite, and manganese","Silver and platinum","Iron ore only"]', 1, 'Ghana exports gold, bauxite, manganese, and diamonds as major minerals.', 'medium', 'multiple_choice', datetime('now')),
('q_geo_res_005', 'subj_wassce_geography', 'topic_geo_resources', 'Sustainable development aims to:', '["Maximize current profits","Meet present needs without compromising future generations","Stop all development","Use only renewable resources"]', 1, 'Sustainable development meets present needs without compromising future generations'' ability to meet their needs.', 'medium', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_geo_afr_001', 'subj_wassce_geography', 'topic_geo_africa', 'The longest river in Africa is:', '["River Congo","River Niger","River Nile","River Zambezi"]', 2, 'The Nile River is the longest in Africa at about 6,650 km.', 'easy', 'multiple_choice', datetime('now')),
('q_geo_afr_002', 'subj_wassce_geography', 'topic_geo_africa', 'The Sahara Desert is located in:', '["Southern Africa","East Africa","Northern Africa","Central Africa"]', 2, 'The Sahara Desert covers most of Northern Africa.', 'easy', 'multiple_choice', datetime('now')),
('q_geo_afr_003', 'subj_wassce_geography', 'topic_geo_africa', 'The Great Rift Valley runs through:', '["West Africa","East Africa","North Africa","Southern Africa"]', 1, 'The Great Rift Valley runs through East Africa from Ethiopia to Mozambique.', 'medium', 'multiple_choice', datetime('now')),
('q_geo_afr_004', 'subj_wassce_geography', 'topic_geo_africa', 'Mount Kilimanjaro is located in:', '["Kenya","Uganda","Tanzania","Ethiopia"]', 2, 'Mount Kilimanjaro, Africa''s highest peak, is located in Tanzania.', 'easy', 'multiple_choice', datetime('now')),
('q_geo_afr_005', 'subj_wassce_geography', 'topic_geo_africa', 'The main cash crop of Ghana is:', '["Coffee","Cocoa","Tea","Rubber"]', 1, 'Cocoa is Ghana''s main cash crop and major export.', 'easy', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_lit_intro_001', 'subj_wassce_literature', 'topic_lit_intro', 'The three main genres of literature are:', '["Novel, poem, essay","Poetry, prose, drama","Fiction, non-fiction, biography","Tragedy, comedy, history"]', 1, 'The three main genres are poetry, prose (fiction and non-fiction), and drama.', 'easy', 'multiple_choice', datetime('now')),
('q_lit_intro_002', 'subj_wassce_literature', 'topic_lit_intro', 'Theme in literature refers to:', '["The setting of a story","The central idea or message","The main character","The style of writing"]', 1, 'Theme is the central idea, message, or insight about life that the author conveys.', 'easy', 'multiple_choice', datetime('now')),
('q_lit_intro_003', 'subj_wassce_literature', 'topic_lit_intro', 'The protagonist in a story is:', '["The villain","The main character","The narrator","A minor character"]', 1, 'The protagonist is the main character around whom the story revolves.', 'easy', 'multiple_choice', datetime('now')),
('q_lit_intro_004', 'subj_wassce_literature', 'topic_lit_intro', 'Setting in literature includes:', '["Time and place of the story","Only the country","Only the time period","The author''s biography"]', 0, 'Setting encompasses both the time period and place where the story occurs.', 'easy', 'multiple_choice', datetime('now')),
('q_lit_intro_005', 'subj_wassce_literature', 'topic_lit_intro', 'Conflict in a story is:', '["The ending","The struggle between opposing forces","The moral lesson","The narrative technique"]', 1, 'Conflict is the struggle between opposing forces that drives the plot.', 'easy', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_lit_afr_001', 'subj_wassce_literature', 'topic_lit_african', 'Chinua Achebe is famous for writing:', '["The Beautyful Ones Are Not Yet Born","Things Fall Apart","Weep Not, Child","The Lion and the Jewel"]', 1, 'Chinua Achebe''s "Things Fall Apart" is a seminal work of African literature.', 'easy', 'multiple_choice', datetime('now')),
('q_lit_afr_002', 'subj_wassce_literature', 'topic_lit_african', 'A common theme in African literature is:', '["Space exploration","Colonialism and its effects","Medieval warfare","Arctic survival"]', 1, 'Many African literary works explore themes of colonialism, identity, and cultural conflict.', 'medium', 'multiple_choice', datetime('now')),
('q_lit_afr_003', 'subj_wassce_literature', 'topic_lit_african', 'Wole Soyinka won the Nobel Prize for:', '["Physics","Literature","Peace","Economics"]', 1, 'Wole Soyinka won the Nobel Prize for Literature in 1986, the first African to do so.', 'medium', 'multiple_choice', datetime('now')),
('q_lit_afr_004', 'subj_wassce_literature', 'topic_lit_african', 'Oral literature includes:', '["Only written poems","Folktales, myths, and proverbs","Newspaper articles","Academic essays"]', 1, 'Oral literature encompasses folktales, myths, legends, proverbs, and songs passed down orally.', 'easy', 'multiple_choice', datetime('now')),
('q_lit_afr_005', 'subj_wassce_literature', 'topic_lit_african', '"The Beautyful Ones Are Not Yet Born" was written by:', '["Chinua Achebe","Ngugi wa Thiong''o","Ayi Kwei Armah","Wole Soyinka"]', 2, 'Ayi Kwei Armah, a Ghanaian author, wrote "The Beautyful Ones Are Not Yet Born."', 'medium', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_crs_kings_001', 'subj_wassce_crs', 'topic_crs_kings', 'The first king of Israel was:', '["David","Solomon","Saul","Samuel"]', 2, 'Saul was anointed by Samuel as the first king of Israel (1 Samuel 10).', 'easy', 'multiple_choice', datetime('now')),
('q_crs_kings_002', 'subj_wassce_crs', 'topic_crs_kings', 'King Solomon was known for his:', '["Military conquests","Wisdom","Prophecies","Miracles"]', 1, 'Solomon was renowned for his wisdom, granted by God (1 Kings 3).', 'easy', 'multiple_choice', datetime('now')),
('q_crs_kings_003', 'subj_wassce_crs', 'topic_crs_kings', 'Elijah challenged the prophets of Baal on:', '["Mount Sinai","Mount Carmel","Mount Zion","Mount Nebo"]', 1, 'Elijah''s confrontation with Baal''s prophets occurred on Mount Carmel (1 Kings 18).', 'medium', 'multiple_choice', datetime('now')),
('q_crs_kings_004', 'subj_wassce_crs', 'topic_crs_kings', 'The prophet who was swallowed by a great fish was:', '["Elijah","Elisha","Jonah","Isaiah"]', 2, 'Jonah was swallowed by a great fish when fleeing from God''s call (Jonah 1-2).', 'easy', 'multiple_choice', datetime('now')),
('q_crs_kings_005', 'subj_wassce_crs', 'topic_crs_kings', 'David killed Goliath with:', '["A sword","A spear","A sling and stone","An arrow"]', 2, 'David defeated Goliath with a sling and stone (1 Samuel 17).', 'easy', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_crs_passion_001', 'subj_wassce_crs', 'topic_crs_passion', 'Jesus was crucified at:', '["Bethlehem","Nazareth","Golgotha","Jericho"]', 2, 'Jesus was crucified at Golgotha (also called Calvary), meaning "place of the skull."', 'easy', 'multiple_choice', datetime('now')),
('q_crs_passion_002', 'subj_wassce_crs', 'topic_crs_passion', 'The disciple who betrayed Jesus was:', '["Peter","James","John","Judas Iscariot"]', 3, 'Judas Iscariot betrayed Jesus for thirty pieces of silver (Matthew 26:14-16).', 'easy', 'multiple_choice', datetime('now')),
('q_crs_passion_003', 'subj_wassce_crs', 'topic_crs_passion', 'Jesus rose from the dead on:', '["The first day","The second day","The third day","The seventh day"]', 2, 'Jesus rose on the third day after his crucifixion, as he had predicted.', 'easy', 'multiple_choice', datetime('now')),
('q_crs_passion_004', 'subj_wassce_crs', 'topic_crs_passion', 'The Last Supper was:', '["A wedding feast","The Passover meal","A Sabbath dinner","A birthday celebration"]', 1, 'The Last Supper was the Passover meal Jesus shared with his disciples before his arrest.', 'medium', 'multiple_choice', datetime('now')),
('q_crs_passion_005', 'subj_wassce_crs', 'topic_crs_passion', 'Who discovered the empty tomb first?', '["Peter","John","Mary Magdalene","Thomas"]', 2, 'Mary Magdalene was the first to discover the empty tomb (John 20:1).', 'medium', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_crs_church_001', 'subj_wassce_crs', 'topic_crs_church', 'The Holy Spirit came upon the disciples at:', '["Christmas","Easter","Pentecost","Passover"]', 2, 'The Holy Spirit descended on the disciples at Pentecost (Acts 2).', 'easy', 'multiple_choice', datetime('now')),
('q_crs_church_002', 'subj_wassce_crs', 'topic_crs_church', 'The first Christian martyr was:', '["Peter","Paul","Stephen","James"]', 2, 'Stephen was stoned to death, becoming the first Christian martyr (Acts 7).', 'medium', 'multiple_choice', datetime('now')),
('q_crs_church_003', 'subj_wassce_crs', 'topic_crs_church', 'Saul of Tarsus was converted on the road to:', '["Jerusalem","Damascus","Rome","Athens"]', 1, 'Saul (later Paul) encountered Jesus on the road to Damascus (Acts 9).', 'easy', 'multiple_choice', datetime('now')),
('q_crs_church_004', 'subj_wassce_crs', 'topic_crs_church', 'The apostle to the Gentiles was:', '["Peter","James","Paul","John"]', 2, 'Paul is known as the apostle to the Gentiles, spreading Christianity beyond Judaism.', 'easy', 'multiple_choice', datetime('now')),
('q_crs_church_005', 'subj_wassce_crs', 'topic_crs_church', 'The early Christians were first called Christians at:', '["Jerusalem","Antioch","Rome","Corinth"]', 1, 'The disciples were first called Christians in Antioch (Acts 11:26).', 'medium', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_ict_db_001', 'subj_wassce_ict', 'topic_ict_database', 'A database is:', '["A word processor","An organized collection of related data","A spreadsheet","An email client"]', 1, 'A database is an organized collection of structured data that can be easily accessed and managed.', 'easy', 'multiple_choice', datetime('now')),
('q_ict_db_002', 'subj_wassce_ict', 'topic_ict_database', 'A record in a database is:', '["A single piece of data","A complete set of related fields","A column","The database name"]', 1, 'A record (or row) contains a complete set of related fields for one entry.', 'easy', 'multiple_choice', datetime('now')),
('q_ict_db_003', 'subj_wassce_ict', 'topic_ict_database', 'A primary key is:', '["Any field in a table","A unique identifier for each record","A foreign key","A calculated field"]', 1, 'A primary key uniquely identifies each record in a database table.', 'medium', 'multiple_choice', datetime('now')),
('q_ict_db_004', 'subj_wassce_ict', 'topic_ict_database', 'SQL stands for:', '["Simple Query Language","Structured Query Language","System Query Language","Standard Query Language"]', 1, 'SQL stands for Structured Query Language, used to manage databases.', 'easy', 'multiple_choice', datetime('now')),
('q_ict_db_005', 'subj_wassce_ict', 'topic_ict_database', 'A query is used to:', '["Print documents","Retrieve specific data from a database","Create graphics","Send emails"]', 1, 'A query retrieves specific data from a database based on defined criteria.', 'easy', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_ict_wp_001', 'subj_wassce_ict', 'topic_ict_word', 'Microsoft Word is a:', '["Spreadsheet application","Word processing application","Database application","Presentation software"]', 1, 'Microsoft Word is a word processing application for creating and editing documents.', 'easy', 'multiple_choice', datetime('now')),
('q_ict_wp_002', 'subj_wassce_ict', 'topic_ict_word', 'To make text bold in Word, you press:', '["Ctrl + I","Ctrl + B","Ctrl + U","Ctrl + P"]', 1, 'Ctrl + B is the keyboard shortcut to make text bold.', 'easy', 'multiple_choice', datetime('now')),
('q_ict_wp_003', 'subj_wassce_ict', 'topic_ict_word', 'The default file extension for Word documents is:', '[".txt",".docx",".xlsx",".pptx"]', 1, '.docx is the default file extension for Microsoft Word documents.', 'easy', 'multiple_choice', datetime('now')),
('q_ict_wp_004', 'subj_wassce_ict', 'topic_ict_word', 'Mail merge is used to:', '["Send emails","Create personalized documents for multiple recipients","Merge two documents","Print in color"]', 1, 'Mail merge creates personalized letters or labels for multiple recipients from a data source.', 'medium', 'multiple_choice', datetime('now')),
('q_ict_wp_005', 'subj_wassce_ict', 'topic_ict_word', 'To undo an action in Word, press:', '["Ctrl + Y","Ctrl + Z","Ctrl + X","Ctrl + V"]', 1, 'Ctrl + Z undoes the last action in Word and many other applications.', 'easy', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_ict_ss_001', 'subj_wassce_ict', 'topic_ict_spreadsheet', 'A cell in a spreadsheet is identified by:', '["Row number only","Column letter only","Row number and column letter","Cell name"]', 2, 'A cell is identified by its column letter and row number (e.g., A1, B5).', 'easy', 'multiple_choice', datetime('now')),
('q_ict_ss_002', 'subj_wassce_ict', 'topic_ict_spreadsheet', 'The formula =SUM(A1:A5) will:', '["Multiply cells A1 to A5","Add cells A1 to A5","Find average of A1 to A5","Count cells A1 to A5"]', 1, 'SUM adds all values in the specified range (A1 through A5).', 'easy', 'multiple_choice', datetime('now')),
('q_ict_ss_003', 'subj_wassce_ict', 'topic_ict_spreadsheet', 'Which symbol starts a formula in Excel?', '["@","+","=","#"]', 2, 'All formulas in Excel must begin with an equals sign (=).', 'easy', 'multiple_choice', datetime('now')),
('q_ict_ss_004', 'subj_wassce_ict', 'topic_ict_spreadsheet', 'A chart in a spreadsheet is used to:', '["Store data","Visually represent data","Calculate formulas","Print documents"]', 1, 'Charts provide visual representation of data for easier analysis and presentation.', 'easy', 'multiple_choice', datetime('now')),
('q_ict_ss_005', 'subj_wassce_ict', 'topic_ict_spreadsheet', 'The function =AVERAGE(B1:B10) calculates:', '["Total of B1 to B10","Mean of B1 to B10","Maximum of B1 to B10","Minimum of B1 to B10"]', 1, 'AVERAGE calculates the arithmetic mean of the values in the range.', 'easy', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_his_ww_001', 'subj_wassce_history', 'topic_his_worldwar', 'World War I began in:', '["1912","1914","1918","1920"]', 1, 'World War I began in 1914, triggered by the assassination of Archduke Franz Ferdinand.', 'easy', 'multiple_choice', datetime('now')),
('q_his_ww_002', 'subj_wassce_history', 'topic_his_worldwar', 'World War II ended in:', '["1943","1944","1945","1946"]', 2, 'World War II ended in 1945 with the surrender of Germany and Japan.', 'easy', 'multiple_choice', datetime('now')),
('q_his_ww_003', 'subj_wassce_history', 'topic_his_worldwar', 'The Treaty of Versailles was signed after:', '["World War II","World War I","The Cold War","The Korean War"]', 1, 'The Treaty of Versailles was signed in 1919, ending World War I.', 'medium', 'multiple_choice', datetime('now')),
('q_his_ww_004', 'subj_wassce_history', 'topic_his_worldwar', 'The United Nations was formed in:', '["1919","1939","1945","1950"]', 2, 'The United Nations was established in 1945 after World War II.', 'medium', 'multiple_choice', datetime('now')),
('q_his_ww_005', 'subj_wassce_history', 'topic_his_worldwar', 'Hitler was the leader of:', '["Italy","Germany","Japan","Soviet Union"]', 1, 'Adolf Hitler was the leader of Nazi Germany during World War II.', 'easy', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_his_cw_001', 'subj_wassce_history', 'topic_his_coldwar', 'The Cold War was primarily between:', '["Britain and France","USA and Soviet Union","China and Japan","Germany and Italy"]', 1, 'The Cold War was the rivalry between the USA and Soviet Union from 1947-1991.', 'easy', 'multiple_choice', datetime('now')),
('q_his_cw_002', 'subj_wassce_history', 'topic_his_coldwar', 'The Berlin Wall fell in:', '["1985","1987","1989","1991"]', 2, 'The Berlin Wall fell on November 9, 1989, symbolizing the end of the Cold War.', 'medium', 'multiple_choice', datetime('now')),
('q_his_cw_003', 'subj_wassce_history', 'topic_his_coldwar', 'NATO stands for:', '["North American Treaty Organization","North Atlantic Treaty Organization","National Alliance Treaty Organization","Northern Atlantic Treaty Order"]', 1, 'NATO is the North Atlantic Treaty Organization, formed in 1949.', 'medium', 'multiple_choice', datetime('now')),
('q_his_cw_004', 'subj_wassce_history', 'topic_his_coldwar', 'The Soviet Union collapsed in:', '["1985","1989","1991","1993"]', 2, 'The Soviet Union dissolved in December 1991.', 'medium', 'multiple_choice', datetime('now')),
('q_his_cw_005', 'subj_wassce_history', 'topic_his_coldwar', 'The Iron Curtain referred to:', '["A metal barrier","The division between Eastern and Western Europe","A trade agreement","A military weapon"]', 1, 'The Iron Curtain was the ideological and physical boundary dividing Europe during the Cold War.', 'medium', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_his_post_001', 'subj_wassce_history', 'topic_his_postcolonial', 'Most African countries gained independence in the:', '["1940s","1960s","1980s","1990s"]', 1, 'The 1960s was the "Year of Africa" with many countries gaining independence.', 'medium', 'multiple_choice', datetime('now')),
('q_his_post_002', 'subj_wassce_history', 'topic_his_postcolonial', 'Apartheid ended in South Africa in:', '["1990","1994","1998","2000"]', 1, 'Apartheid officially ended in 1994 with the first democratic elections.', 'medium', 'multiple_choice', datetime('now')),
('q_his_post_003', 'subj_wassce_history', 'topic_his_postcolonial', 'Nelson Mandela was president of:', '["Nigeria","Ghana","South Africa","Kenya"]', 2, 'Nelson Mandela became South Africa''s first Black president in 1994.', 'easy', 'multiple_choice', datetime('now')),
('q_his_post_004', 'subj_wassce_history', 'topic_his_postcolonial', 'A major challenge facing post-colonial Africa is:', '["Too much democracy","Tribalism and ethnic conflict","Excessive development","Too many resources"]', 1, 'Ethnic conflict and tribalism have been significant challenges in many post-colonial African nations.', 'medium', 'multiple_choice', datetime('now')),
('q_his_post_005', 'subj_wassce_history', 'topic_his_postcolonial', 'Julius Nyerere promoted:', '["Capitalism","African socialism (Ujamaa)","Colonialism","Apartheid"]', 1, 'Julius Nyerere of Tanzania promoted Ujamaa, a form of African socialism.', 'medium', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_his_nig_001', 'subj_wassce_history', 'topic_his_nigeria', 'Nigeria gained independence in:', '["1957","1960","1963","1966"]', 1, 'Nigeria gained independence from Britain on October 1, 1960.', 'easy', 'multiple_choice', datetime('now')),
('q_his_nig_002', 'subj_wassce_history', 'topic_his_nigeria', 'The Nigerian Civil War occurred between:', '["1960-1963","1967-1970","1975-1979","1980-1983"]', 1, 'The Nigerian Civil War (Biafran War) lasted from 1967 to 1970.', 'medium', 'multiple_choice', datetime('now')),
('q_his_nig_003', 'subj_wassce_history', 'topic_his_nigeria', 'Nigeria''s first president was:', '["Nnamdi Azikiwe","Obafemi Awolowo","Ahmadu Bello","Abubakar Tafawa Balewa"]', 0, 'Nnamdi Azikiwe became Nigeria''s first president in 1963.', 'medium', 'multiple_choice', datetime('now')),
('q_his_nig_004', 'subj_wassce_history', 'topic_his_nigeria', 'The amalgamation of Northern and Southern Nigeria occurred in:', '["1900","1914","1946","1960"]', 1, 'The Northern and Southern Protectorates were amalgamated in 1914 by Lord Lugard.', 'medium', 'multiple_choice', datetime('now')),
('q_his_nig_005', 'subj_wassce_history', 'topic_his_nigeria', 'The major ethnic groups in Nigeria are:', '["Yoruba, Igbo, and Hausa","Zulu, Xhosa, and Sotho","Akan, Ewe, and Ga","Kikuyu, Luo, and Maasai"]', 0, 'The three major ethnic groups in Nigeria are Yoruba, Igbo, and Hausa-Fulani.', 'easy', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_his_au_001', 'subj_wassce_history', 'topic_his_oau', 'The OAU was founded in:', '["1960","1963","1975","1980"]', 1, 'The Organization of African Unity (OAU) was founded in 1963 in Addis Ababa.', 'medium', 'multiple_choice', datetime('now')),
('q_his_au_002', 'subj_wassce_history', 'topic_his_oau', 'The OAU was replaced by the African Union in:', '["1999","2002","2005","2010"]', 1, 'The African Union replaced the OAU in 2002.', 'medium', 'multiple_choice', datetime('now')),
('q_his_au_003', 'subj_wassce_history', 'topic_his_oau', 'The headquarters of the African Union is in:', '["Nairobi, Kenya","Cairo, Egypt","Addis Ababa, Ethiopia","Lagos, Nigeria"]', 2, 'The African Union is headquartered in Addis Ababa, Ethiopia.', 'easy', 'multiple_choice', datetime('now')),
('q_his_au_004', 'subj_wassce_history', 'topic_his_oau', 'A major goal of the OAU was:', '["Promoting colonialism","Ending colonialism and apartheid","Supporting European powers","Dividing Africa"]', 1, 'The OAU''s main goals included ending colonialism and apartheid in Africa.', 'easy', 'multiple_choice', datetime('now')),
('q_his_au_005', 'subj_wassce_history', 'topic_his_oau', 'Kwame Nkrumah was a key advocate for:', '["African disunity","Pan-Africanism","Colonialism","Apartheid"]', 1, 'Kwame Nkrumah of Ghana was a leading advocate of Pan-Africanism and African unity.', 'easy', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_food_prep_001', 'subj_wassce_foods', 'topic_foods_prep', 'The correct order of food preparation steps is:', '["Cook, clean, prepare","Clean, prepare, cook","Cook, prepare, clean","Prepare, clean, cook"]', 1, 'Proper food preparation follows: cleaning ingredients, preparing/cutting them, then cooking.', 'easy', 'multiple_choice', datetime('now')),
('q_food_prep_002', 'subj_wassce_foods', 'topic_foods_prep', 'Blanching vegetables involves:', '["Deep frying","Brief boiling then cold water immersion","Baking at high heat","Sun drying"]', 1, 'Blanching involves briefly boiling vegetables then plunging them into cold water to stop cooking.', 'medium', 'multiple_choice', datetime('now')),
('q_food_prep_003', 'subj_wassce_foods', 'topic_foods_prep', 'Marinating meat is done to:', '["Make it harder","Add flavor and tenderize","Remove nutrients","Make it dry"]', 1, 'Marinating adds flavor and helps tenderize meat through acidic ingredients.', 'easy', 'multiple_choice', datetime('now')),
('q_food_prep_004', 'subj_wassce_foods', 'topic_foods_prep', 'The danger zone for food temperature is:', '["0-5°C","5-60°C","60-100°C","100-150°C"]', 1, 'The danger zone (5-60°C/40-140°F) is where bacteria multiply rapidly.', 'medium', 'multiple_choice', datetime('now')),
('q_food_prep_005', 'subj_wassce_foods', 'topic_foods_prep', 'FIFO in food storage means:', '["First In, First Out","Food Is For Others","Fast In, Fast Out","Fresh Is For Ordering"]', 0, 'FIFO (First In, First Out) ensures older food is used before newer food.', 'medium', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_food_sci_001', 'subj_wassce_foods', 'topic_foods_science', 'Proteins are made up of:', '["Fatty acids","Amino acids","Glucose molecules","Vitamins"]', 1, 'Proteins are composed of amino acids linked together in chains.', 'easy', 'multiple_choice', datetime('now')),
('q_food_sci_002', 'subj_wassce_foods', 'topic_foods_science', 'Carbohydrates are stored in the body as:', '["Protein","Fat","Glycogen","Vitamins"]', 2, 'Excess carbohydrates are stored as glycogen in the liver and muscles.', 'medium', 'multiple_choice', datetime('now')),
('q_food_sci_003', 'subj_wassce_foods', 'topic_foods_science', 'Oxidation of fats causes:', '["Improved flavor","Rancidity","Better texture","Higher nutrition"]', 1, 'Fat oxidation causes rancidity, giving food an unpleasant taste and smell.', 'medium', 'multiple_choice', datetime('now')),
('q_food_sci_004', 'subj_wassce_foods', 'topic_foods_science', 'Emulsification is:', '["Mixing oil and water with an emulsifier","Separating oil from water","Heating food","Freezing food"]', 0, 'Emulsification combines immiscible liquids (like oil and water) using an emulsifier.', 'medium', 'multiple_choice', datetime('now')),
('q_food_sci_005', 'subj_wassce_foods', 'topic_foods_science', 'Gelatinization occurs when:', '["Starch is heated with water","Proteins are cooled","Fats are frozen","Vitamins are exposed to light"]', 0, 'Gelatinization occurs when starch granules absorb water and swell during heating.', 'medium', 'multiple_choice', datetime('now'));
INSERT INTO questions (id, subject_id, topic_id, question_text, options, correct_answer, explanation, difficulty, question_type, created_at) VALUES
('q_food_diet_001', 'subj_wassce_foods', 'topic_foods_diets', 'A diabetic diet should be:', '["High in sugar","Low in sugar and refined carbohydrates","High in fat","Low in protein"]', 1, 'Diabetic diets should limit sugar and refined carbohydrates to control blood glucose.', 'easy', 'multiple_choice', datetime('now')),
('q_food_diet_002', 'subj_wassce_foods', 'topic_foods_diets', 'People with hypertension should reduce:', '["Vegetables","Salt intake","Fruits","Water"]', 1, 'Reducing salt (sodium) intake helps control high blood pressure.', 'easy', 'multiple_choice', datetime('now')),
('q_food_diet_003', 'subj_wassce_foods', 'topic_foods_diets', 'A vegetarian diet excludes:', '["Vegetables","Meat and fish","Grains","Fruits"]', 1, 'Vegetarians do not eat meat or fish, though some may eat dairy and eggs.', 'easy', 'multiple_choice', datetime('now')),
('q_food_diet_004', 'subj_wassce_foods', 'topic_foods_diets', 'Pregnant women need extra:', '["Sugar","Folic acid and iron","Salt","Fat"]', 1, 'Pregnant women need increased folic acid (for neural development) and iron (for blood volume).', 'medium', 'multiple_choice', datetime('now')),
('q_food_diet_005', 'subj_wassce_foods', 'topic_foods_diets', 'Celiac disease requires avoiding:', '["Lactose","Gluten","Fructose","Sucrose"]', 1, 'People with celiac disease must avoid gluten, found in wheat, barley, and rye.', 'medium', 'multiple_choice', datetime('now'));
