('q_food_cat_001', 'subj_wassce_foods', 'topic_foods_catering', 'Portion control in catering ensures:', '["Larger portions for everyone","Consistent serving sizes and cost control","Random portion sizes","Unlimited food"]', 1, 'Portion control ensures consistent serving sizes, controls costs, and reduces waste.', 'easy', 'multiple_choice', datetime('now')),
('q_food_cat_002', 'subj_wassce_foods', 'topic_foods_catering', 'A banquet is:', '["A small family meal","A formal meal for many guests","Fast food service","Self-service"]', 1, 'A banquet is a formal, elaborate meal served to a large number of guests.', 'easy', 'multiple_choice', datetime('now')),
('q_food_cat_003', 'subj_wassce_foods', 'topic_foods_catering', 'HACCP stands for:', '["Hazard Analysis Critical Control Points","Health And Cleanliness Control Plan","High Alert Catering Control Process","Healthy And Clean Cooking Practices"]', 0, 'HACCP (Hazard Analysis Critical Control Points) is a food safety management system.', 'medium', 'multiple_choice', datetime('now')),
('q_food_cat_004', 'subj_wassce_foods', 'topic_foods_catering', 'Mise en place means:', '["Cooking quickly","Everything in its place (preparation before cooking)","Serving food","Cleaning up"]', 1, 'Mise en place is the culinary practice of preparing and organizing all ingredients before cooking.', 'medium', 'multiple_choice', datetime('now')),
('q_food_cat_005', 'subj_wassce_foods', 'topic_foods_catering', 'The kitchen brigade system was developed by:', '["Julia Child","Gordon Ramsay","Auguste Escoffier","Jamie Oliver"]', 2, 'Auguste Escoffier developed the kitchen brigade system for efficient restaurant operations.', 'hard', 'multiple_choice', datetime('now'));
